import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"I18N","description":"","frontmatter":{"title":"I18N"},"headers":[],"relativePath":"de/api/reference/i18n.md","filePath":"de/api/reference/i18n.md"}`),a={name:`de/api/reference/i18n.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="i18n" tabindex="-1">I18N <a class="header-anchor" href="#i18n" aria-label="Permalink to “I18N”">​</a></h1><div><p>Operationen des Tags <strong>I18N</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="getI18nBundle" tabindex="-1">Dynamic labels for a locale (ADR-025, US-140, REQ-152) <a class="header-anchor" href="#getI18nBundle" aria-label="Permalink to “Dynamic labels for a locale (ADR-025, US-140, REQ-152)”">​</a></h2><p><code>GET /i18n/{locale}</code> · <code>getI18nBundle</code></p><p>All labels of metatypes, property categories, property definitions and enum values for the locale. A key without a label in the locale carries the name in the corporate language. An organization label wins over a package label. The weak <code>ETag</code> is a hash of the bundle content; a matching <code>If-None-Match</code> is answered with 304 and no body. <code>Cache-Control: max-age=300, stale-while-revalidate=3600</code></p><p><strong>Zugriff</strong>: jeder angemeldete Principal</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>locale</code></td><td>path</td><td>ja</td><td>string</td><td>–</td></tr><tr><td><code>If-None-Match</code></td><td>header</td><td>nein</td><td>string</td><td>ETag of the bundle the client already holds</td></tr></tbody></table><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Labels</td><td>–</td></tr><tr><td>304</td><td>Not modified</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};